//! 4-byte BLAKE3 event topic prefixes and log-packing helpers.
//!
//! Per DEX spec §10: topics are 4-byte BLAKE3 prefixes of the event
//! signature string (same rule as method selectors). Data fields are
//! packed per §4 fixed-width encoding (address=32B, u256=32B, u128=16B, etc.).
//!
//! These constants are generated by `build.rs`.

#[cfg(not(feature = "std"))]
use alloc::vec::Vec;

include!(concat!(env!("OUT_DIR"), "/events_generated.rs"));

/// Pack a `Transfer(from, to, value)` log payload.
///
/// Topics: `[ERC20_TRANSFER_EVENT]`
/// Data: `from (32) || to (32) || value (32)`
pub fn pack_transfer(from: &[u8; 32], to: &[u8; 32], value: &[u8; 32]) -> Vec<u8> {
    let mut v = Vec::with_capacity(96);
    v.extend_from_slice(from);
    v.extend_from_slice(to);
    v.extend_from_slice(value);
    v
}

/// Pack an `Approval(owner, spender, value)` log payload.
pub fn pack_approval(owner: &[u8; 32], spender: &[u8; 32], value: &[u8; 32]) -> Vec<u8> {
    let mut v = Vec::with_capacity(96);
    v.extend_from_slice(owner);
    v.extend_from_slice(spender);
    v.extend_from_slice(value);
    v
}

/// Pack a `Mint(sender, amount0, amount1)` log payload.
pub fn pack_mint(sender: &[u8; 32], amount0: &[u8; 32], amount1: &[u8; 32]) -> Vec<u8> {
    let mut v = Vec::with_capacity(96);
    v.extend_from_slice(sender);
    v.extend_from_slice(amount0);
    v.extend_from_slice(amount1);
    v
}

