/// Pack a `Swap(sender, a0in, a1in, a0out, a1out, to)` log payload.
pub fn pack_swap(
    sender: &[u8; 32],
    a0in: &[u8; 32],
    a1in: &[u8; 32],
    a0out: &[u8; 32],
    a1out: &[u8; 32],
    to: &[u8; 32],
) -> Vec<u8> {
    let mut v = Vec::with_capacity(192);
    v.extend_from_slice(sender);
    v.extend_from_slice(a0in);
    v.extend_from_slice(a1in);
    v.extend_from_slice(a0out);
    v.extend_from_slice(a1out);
    v.extend_from_slice(to);
    v
}

/// Pack a `Sync(reserve0, reserve1)` log payload.
///
/// `reserve0` and `reserve1` are `u128`, so 16 bytes each.
pub fn pack_sync(reserve0: u128, reserve1: u128) -> Vec<u8> {
    let mut v = Vec::with_capacity(32);
    v.extend_from_slice(&reserve0.to_be_bytes());
    v.extend_from_slice(&reserve1.to_be_bytes());
    v
}

/// Pack a `PairCreated(token0, token1, pair, index)` log payload.
///
/// `index` is `u64`.
pub fn pack_pair_created(
    token0: &[u8; 32],
    token1: &[u8; 32],
    pair: &[u8; 32],
    index: u64,
) -> Vec<u8> {
    let mut v = Vec::with_capacity(104);
    v.extend_from_slice(token0);
    v.extend_from_slice(token1);
    v.extend_from_slice(pair);
    v.extend_from_slice(&index.to_be_bytes());
    v
}
